sysauto_script.script:
(function() {
    // Pega a data atual (apenas data, sem hora)
    var today = new GlideDateTime();
    var todayStr = today.getLocalDate().toString(); // formato YYYY-MM-DD

    // Busca agendas ativas com a data de hoje
    var agendaGR = new GlideRecord('x_1795292_learni_0_agenda');
    agendaGR.addQuery('course_date', todayStr);
    agendaGR.addQuery('active', true);
    agendaGR.query();

    while (agendaGR.next()) {
        var instructor = agendaGR.course_instructor;
        if (!instructor) continue;

        // Busca matrículas ligadas a esta agenda
        var enrollmentList = [];
        var enrollmentGR = new GlideRecord('x_1795292_learni_0_enrollment');
        enrollmentGR.addQuery('training_date', agendaGR.sys_id); 
        enrollmentGR.query();

        while (enrollmentGR.next()) {
            if (enrollmentGR.student) {
                enrollmentList.push(enrollmentGR.student.getDisplayValue());
            }
        }

        // Monta corpo do e-mail
        var body = 'Olá ' + instructor.getDisplayValue() + ',<br><br>';
        body += 'Segue a lista de matriculados para o treinamento <b>' + agendaGR.title_course.getDisplayValue() + '</b> no dia de hoje (' + agendaGR.course_date.getDisplayValue() + '):<br><br>';

        if (enrollmentList.length > 0) {
            body += enrollmentList.join('<br>');
        } else {
            body += '(Nenhum aluno matriculado no momento)';
        }

        body += '<br><br>Atenciosamente,<br>Sistema Learning Now';

        gs.eventQueueEmailDirect(
            '', 
            instructor.email.toString(),
            'Lista de matriculados — ' + agendaGR.title_course.getDisplayValue(),
            body
        );
    }
})();
